const companies = $input.first().json;
const list = Array.isArray(companies) ? companies : (companies ? [companies] : []);
if (list.length === 0) return [];

return list.map(c => ({ json: c }));

const company = $input.first().json;
const platform = (company.platform || 'unknown').toLowerCase();
const url = company.careers_url;
const name = company.name;

let jobs = [];

// Greenhouse board API
if (platform === 'greenhouse') {
  const token = company.board_token || '';
  const boardSlug = url.match(/boards\.greenhouse\.io\/([\w.-]+)/)?.[1] || '';
  if (!boardSlug) return [];
  const apiUrl = `https://boards-api.greenhouse.io/v1/boards/${boardSlug}/jobs?content=true`;
  try {
    const resp = await fetch(apiUrl);
    if (!resp.ok) return [];
    const data = await resp.json();
    jobs = (data.jobs || []).map(j => ({
      title: j.title || '',
      description: (j.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000),
      url: j.absolute_url || `https://boards.greenhouse.io/${boardSlug}/jobs/${j.id}`,
      location: (j.location && j.location.name) || '',
      skills: (j.departments || []).map(d => d.name).filter(Boolean),
      posted_at: j.updated_at || j.created_at || new Date().toISOString(),
    }));
  } catch { return []; }
}

// Lever job board API
else if (platform === 'lever') {
  const leverHost = new URL(url).hostname;
  const teamSlug = leverHost.replace('jobs.lever.co/', '');
  const apiUrl = `https://api.lever.co/v0/postings/${teamSlug}?mode=json`;
  try {
    const resp = await fetch(apiUrl);
    if (!resp.ok) return [];
    const data = await resp.json();
    jobs = (Array.isArray(data) ? data : []).map(j => ({
      title: j.text || '',
      description: (j.descriptionPlain || j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000),
      url: j.hostedUrl || url,
      location: (j.categories && j.categories.location) || '',
      skills: (j.tags || []),
      posted_at: j.createdAt ? new Date(j.createdAt).toISOString() : new Date().toISOString(),
    }));
  } catch { return []; }
}

// Ashby API
else if (platform === 'ashby') {
  const orgSlug = url.match(/ashbyhq\.com\/([\w.-]+)/)?.[1] || '';
  if (!orgSlug) return [];
  const apiUrl = `https://api.ashbyhq.com/posting-api/job-board/${orgSlug}`;
  try {
    const resp = await fetch(apiUrl);
    if (!resp.ok) return [];
    const data = await resp.json();
    jobs = (data.jobs || []).map(j => ({
      title: j.title || '',
      description: (j.descriptionPlain || j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000),
      url: j.url || url,
      location: (j.locationName || ''),
      skills: (j.teamName ? [j.teamName] : []),
      posted_at: j.publishedAt || new Date().toISOString(),
    }));
  } catch { return []; }
}

// Workable
else if (platform === 'workable') {
  const subdomain = url.match(/([\w-]+)\.workable\.com/)?.[1] || '';
  if (!subdomain) return [];
  const apiUrl = `https://${subdomain}.workable.com/spider/v1/api/accounts/${subdomain}/jobs`;
  try {
    const resp = await fetch(apiUrl);
    if (!resp.ok) return [];
    const data = await resp.json();
    jobs = (data.jobs || []).map(j => ({
      title: j.title || '',
      description: (j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000),
      url: j.url || url,
      location: (j.region || j.city || ''),
      skills: (j.tags || []),
      posted_at: j.published_at || new Date().toISOString(),
    }));
  } catch { return []; }
}

// SmartRecruiters
else if (platform === 'smartrecruiters') {
  const apiUrl = `https://api.smartrecruiters.com/v1/companies/${encodeURIComponent(name)}/postings?limit=100`;
  try {
    const resp = await fetch(apiUrl);
    if (!resp.ok) return [];
    const data = await resp.json();
    jobs = (data.content || []).map(j => ({
      title: j.name || '',
      description: (j.jobAd && j.jobAd.sections && j.jobAd.sections.generalDescription || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000),
      url: j.ref || j.applyUrl || url,
      location: (j.location && j.location.city) || '',
      skills: (j.jobAd && j.jobAd.sections && j.jobAd.sections.employmentExperience || '').split(',').map(s => s.trim()).filter(Boolean),
      posted_at: j.releasedDate || new Date().toISOString(),
    }));
  } catch { return []; }
}

// Personio (public API not available — skip gracefully)
else if (platform === 'personio') {
  return [];
}

// Recruitee
else if (platform === 'recruitee') {
  const apiUrl = `https://api.recruitee.com/v1/careers/${company.board_token || name.toLowerCase().replace(/\s+/g, '')}/jobs`;
  try {
    const resp = await fetch(apiUrl);
    if (!resp.ok) return [];
    const data = await resp.json();
    jobs = (data.jobs || []).map(j => ({
      title: j.title || '',
      description: (j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000),
      url: j.url || url,
      location: (j.location || ''),
      skills: [],
      posted_at: j.created_at || new Date().toISOString(),
    }));
  } catch { return []; }
}

// Unknown platform — skip
else {
  return [];
}

// Enrich each job with company metadata
return jobs.map(j => ({ json: { ...j, company_name: name, careers_url: url } }));

// Broad 4-pillar keyword any-match filter.
const job = $input.first().json;
const text = ((job.title || '') + ' ' + (job.description || '') + ' ' + (job.skills || []).join(' ')).toLowerCase();

const KEYWORDS = [
  // design
  'design', 'ux', 'ui', 'figma', 'product designer', 'web design',
  // build
  'developer', 'engineer', 'full-stack', 'fullstack', 'frontend', 'front-end',
  'backend', 'back-end', 'ai', 'llm', 'gpt', 'machine learning',
  // automation
  'automation', 'workflow', 'integration', 'n8n', 'zapier', 'make.com', 'api', 'crm',
  // growth
  'growth', 'marketing', 'seo', 'ads', 'paid media', 'lifecycle',
  'email marketing', 'performance marketing',
];

const matched = KEYWORDS.some(kw => text.includes(kw));
if (!matched) return [];

return [{ json: job }];

// Normalize an ATS job into the jobs table schema.
const input = $input.first().json;

const isRemote = (input.location || '').toLowerCase().includes('remote')
  || (input.description || '').toLowerCase().includes('remote');

return {
  json: {
    source: 'ats_api',
    raw_payload: input,
    title: input.title || 'Untitled',
    description: input.description || '',
    skills_requested: Array.isArray(input.skills) ? input.skills : [],
    budget_min: null,
    budget_max: null,
    budget_type: 'salary',
    client_rating: null,
    client_reviews_count: null,
    client_jobs_posted: null,
    client_hire_rate: null,
    proposals_count: null,
    posted_at: input.posted_at || new Date().toISOString(),
    url: input.url || '',
    ingested_at: new Date().toISOString(),
    company_name: input.company_name || null,
    location: input.location || null,
    is_remote: isRemote,
  }
};
